    "Problem": {
      "fields": [
        "type",
        "title",
        "status",
        "detail",
        "code",
        "instance",
        "requestId",
        "traceId",
        "retryable",
        "issues",
        "retryAfterSeconds",
        "limit",
        "refineScope",
        "resetRequired",
        "retainedFrom",
        "retryWithoutAfter",
        "reason"
      ],
      "fieldTypes": {
        "type": "uri",
        "title": "string",
        "status": "integer",
        "detail": "string",
        "code": "string",
        "instance": "uri",
        "requestId": "uuid",
        "traceId": "string",
        "retryable": "boolean",
        "issues": "ValidationIssue[]",
        "retryAfterSeconds": "integer",
        "limit": "integer",
        "refineScope": "json",
        "resetRequired": "boolean",
        "retainedFrom": "decimalString",
        "retryWithoutAfter": "boolean",
        "reason": "string"
      },
      "bounds": {
        "additionalMembersMaxBytes": 8000,
        "issuesMaxItems": 50,
        "detailMaxLength": 2000,
        "titleMaxLength": 200
      },
      "optionalFields": [
        "instance",
        "traceId",
        "issues",
        "retryAfterSeconds",
        "limit",
        "refineScope",
        "resetRequired",
        "retainedFrom",
        "retryWithoutAfter",
        "reason"
      ],
      "additionalProperties": "bounded JSON extension members; server allowlists by problem type, client ignores unknown members",
      "rules": [
        "RFC 9457 type is the primary identifier; code is its stable Bakery registry alias. Validate their agreement for known Bakery types.",
        "HTTP Problem responses use application/problem+json and body.status equals the actual HTTP status. An embedded MCP problem describes the equivalent REST/domain status, not the successful JSON-RPC envelope HTTP status.",
        "Optional URI/string members are omitted rather than null. Extension members such as issues, limit and retryAfterSeconds are top-level, with no nested extensions wrapper.",
        "A STATE_CONFLICT caused by an expired or out-of-range sync cursor sets resetRequired=true, supplies the retainedFrom boundary, and sets retryWithoutAfter=true so the client can request a fresh snapshot.",
        "A STATE_CONFLICT whose cause is a named state rule sets reason to that stable lowercase snake_case slug (for example approval_required, approval_unavailable, task_not_startable) so a client can tell the rules apart without parsing prose. The slug is bounded to 64 characters; any other value is dropped.",
        "Params cannot override type, title, status, detail, instance, code or correlation IDs. Whitelist/redact known extensions; never serialize Error, cause, stack, SQL, raw provider payloads, secrets or submitted invalid values."
      ],
      "description": "RFC 9457 problem-details body returned for every Bakery REST/MCP/WS failure: `type` is the primary identifier, `code` its stable registry alias, and `status` matches the actual response status, with `requestId`/`traceId` for correlation. `issues`, `retryAfterSeconds`, `reason`, and the sync-specific reset fields are present only when that failure kind applies.",
      "fieldDescriptions": {
        "type": "RFC 9457 URI identifying the problem type.",
        "title": "Human-readable title presented for the problem response.",
        "status": "Current lifecycle status of the record.",
        "detail": "Human-readable detail explaining the response outcome.",
        "code": "Stable Bakery code identifying the response outcome.",
        "instance": "URI identifying the request instance that produced the response.",
        "requestId": "Request identifier used to correlate the response with server logs.",
        "traceId": "W3C trace identifier used to correlate work across services.",
        "retryable": "Whether retrying the failed operation may succeed.",
        "issues": "Structured validation issues returned with the response.",
        "retryAfterSeconds": "Number of seconds the client should wait before retrying.",
        "limit": "Maximum number of values permitted by the response contract.",
        "refineScope": "Validated scope information used to refine the response behavior.",
        "resetRequired": "Whether the client must discard its local state and request a fresh snapshot.",
        "retainedFrom": "Earliest retained event sequence that can be used to establish a fresh sync position.",
        "retryWithoutAfter": "Whether the client should retry the sync request without its after cursor.",
        "reason": "Stable lowercase snake_case slug naming the state rule a 409 STATE_CONFLICT refused on, such as approval_required or approval_unavailable; absent when the conflict has no named rule."
      }
    },
